const e=JSON.parse(`[{"id":"211-san-diego","pillar":"Free Independent Personal Housing","name":"2-1-1 San Diego","provides":"A free 24-hour phone and online service that connects you to housing, food, health, and other help.","eligibility":"Anyone in San Diego County","apply":"Dial 2-1-1 or search the database at 211sandiego.org","phone":"2-1-1","url":"https://211sandiego.org/","status":"Open","status_note":"Always open; not a waitlist","source":"https://211sandiego.org/","date_checked":"2026-09-04"},{"id":"sdhc-hcv-section8","pillar":"Free Independent Personal Housing","name":"San Diego Housing Commission - Section 8 Housing Choice Vouchers","provides":"A federal rent voucher that helps low-income households pay rent in private apartments.","eligibility":"Low-income households in the City of San Diego; must meet federal rules","apply":"Check the SDHC waitlist portal at waitlist.sdhc.org for reopening announcements","phone":"(619) 578-7777","url":"https://www.sdhc.org/","status":"Waitlist closed","status_note":"Closed Feb 1, 2026; watch portal for reopening","source":"https://waitlist.sdhc.org/","date_checked":"2026-09-04"},{"id":"hacsd-county-vouchers","pillar":"Free Independent Personal Housing","name":"Housing Authority of the County of San Diego (HACSD) - Rental Assistance","provides":"County-run rent help, including Section 8 vouchers, for areas outside the cities of San Diego and Chula Vista.","eligibility":"Low-income households in HACSD service area; varies by program","apply":"Call HACSD rental assistance or check sandiegocounty.gov rental assistance page before applying","phone":"(858) 694-4801","url":"https://www.sandiegocounty.gov/hcd/rental_assistance.html","status":"Waitlist closed","status_note":"","source":"https://www.sandiegocounty.gov/hcd/rental_assistance.html","date_checked":"2026-09-04"},{"id":"project-based-vouchers","pillar":"Free Independent Personal Housing","name":"Project-Based Voucher Buildings (County / SDHC)","provides":"Rent help tied to specific apartment buildings so tenants pay less rent each month.","eligibility":"varies","apply":"Call 2-1-1 or the housing authority to ask about any open building waitlists","url":"https://www.sandiegocounty.gov/hcd/rental_assistance.html","status":"Waitlist closed","status_note":"Availability varies per building; confirm individually","source":"https://www.sandiegocounty.gov/hcd/rental_assistance.html","date_checked":"2026-09-04"},{"id":"sdhc-moving-home-rrh","pillar":"Free Independent Personal Housing","name":"SDHC Moving Home Rapid Re-Housing (Housing First San Diego)","provides":"Short-term rent help plus case management to move people off the street into housing fast.","eligibility":"People experiencing homelessness in the City of San Diego, by referral","apply":"Call 2-1-1 to get connected to Coordinated Entry and ask about rapid re-housing","phone":"(619) 578-7777","url":"https://www.sdhc.org/homelessness-solutions/","status":"Confirm current status","status_note":"Referral-based via Coordinated Entry, not open application","source":"https://www.sdhc.org/homelessness-solutions/","date_checked":"2026-09-04"},{"id":"fhcsd","pillar":"Free Universal Health","name":"Family Health Centers of San Diego","provides":"Low-cost health, dental, and mental health care with fees based on your income.","eligibility":"Anyone; sliding fee scale by income and family size, no one turned away for inability to pay","apply":"Call to schedule an appointment or walk into a clinic site","phone":"(619) 515-2300","url":"https://www.fhcsd.org/","status":"Open","status_note":"","source":"https://www.fhcsd.org/","date_checked":"2026-09-04"},{"id":"vista-community-clinic","pillar":"Free Universal Health","name":"Vista Community Clinic","provides":"Low-cost primary care, dental, and other health services in North County.","eligibility":"Anyone; uninsured patients can get help enrolling or pay on a sliding fee scale","apply":"Call to schedule an appointment","phone":"(760) 631-5000","url":"https://vistacommunityclinic.org/","status":"Open","status_note":"","source":"https://vistacommunityclinic.org/","date_checked":"2026-09-04"},{"id":"calfresh","pillar":"Free Food Resources","name":"CalFresh (SNAP / EBT)","provides":"Monthly money on a debit-like card to buy groceries at stores and farmers markets.","eligibility":"Low-income California residents; amount depends on income and household size","apply":"Apply online at BenefitsCal.com or call the CalFresh info line","phone":"1-877-847-3663","url":"https://benefitscal.com/","status":"Open","status_note":"Rolling enrollment; no waitlist","source":"https://www.cdss.ca.gov/calfresh","date_checked":"2026-09-04"},{"id":"sd-food-bank","pillar":"Free Food Resources","name":"Jacobs & Cushman San Diego Food Bank","provides":"Free groceries and food boxes handed out at sites across the county each month.","eligibility":"Anyone in need in San Diego County","apply":"Call the toll-free line or use the zip-code finder at sandiegofoodbank.org","phone":"1-866-350-3663","url":"https://sandiegofoodbank.org/","status":"Open","status_note":"","source":"https://sandiegofoodbank.org/","date_checked":"2026-09-04"},{"id":"feeding-san-diego","pillar":"Free Food Resources","name":"Feeding San Diego","provides":"Free food distributions and mobile pantries run with local partners countywide.","eligibility":"Anyone in need in San Diego County","apply":"Find a distribution at feedingsandiego.org/get-help or call for help","phone":"(858) 452-3663","url":"https://feedingsandiego.org/get-help/","status":"Open","status_note":"","source":"https://feedingsandiego.org/get-help/","date_checked":"2026-09-04"},{"id":"father-joes-meals","pillar":"Free Food Resources","name":"Father Joe's Villages - Free Meals","provides":"Free daily meals for people who are hungry or homeless in downtown San Diego.","eligibility":"Low income, homeless, or anyone in need; no documents required","apply":"Walk in to the meal site; call the info line first to confirm times","phone":"(619) 466-3537","url":"https://my.neighbor.org/","status":"Open","status_note":"Confirm serving times","source":"https://my.neighbor.org/","date_checked":"2026-09-04"},{"id":"fresh-start-showers","pillar":"Free Hygiene Resources","name":"Fresh Start Showers (Think Dignity / TACO)","provides":"Free private mobile showers with towels and soap for people experiencing homelessness.","eligibility":"Anyone experiencing homelessness; no ID required, first come first served","apply":"Show up at a scheduled shower site; call Think Dignity to confirm days and times","phone":"619-537-8736","url":"https://www.thinkdignity.org/","status":"Confirm current status","status_note":"Schedule varies","source":"https://www.thinkdignity.org/","date_checked":"2026-09-04"},{"id":"mts-pronto-life","pillar":"Free Zero Entropy Travel","name":"MTS PRONTO LIFE Low-Income Fare","provides":"Cheaper bus and trolley rides for low-income riders on MTS and North County Transit.","eligibility":"Riders enrolled in CalFresh, Medi-Cal, or CalWORKs","apply":"Apply through the MTS PRONTO LIFE page or visit the MTS Transit Store","url":"https://www.sdmts.com/fares","status":"Open","status_note":"","source":"https://www.sdmts.com/fares","date_checked":"2026-09-04"},{"id":"mts-reduced-fare","pillar":"Free Zero Entropy Travel","name":"MTS Reduced Fares - Seniors and Riders with Disabilities","provides":"Cheaper bus and trolley fares for seniors, Medicare riders, and riders with disabilities.","eligibility":"Age 65+, Medicare, SSI/SSDI, or qualifying disability; application required","apply":"Fill out the MTS reduced-fare short or long form and visit the Transit Store","phone":"619-595-5636","url":"https://www.sdmts.com/fares/discounts","status":"Open","status_note":"","source":"https://www.sdmts.com/fares","date_checked":"2026-09-04"},{"id":"sd-workforce-partnership","pillar":"Free Regenerative Independent Personal Income","name":"San Diego Workforce Partnership Career Centers","provides":"Free job search help, training funds, and career coaching at centers across the county.","eligibility":"San Diego County job seekers age 16 and up, any income or background","apply":"Book an appointment at workforce.org/appointments or call the career centers","phone":"(619) 319-9675","url":"https://workforce.org/jobseekers","status":"Open","status_note":"","source":"https://workforce.org/","date_checked":"2026-09-04"},{"id":"urban-corps-sd","pillar":"Free Regenerative Independent Personal Income","name":"Urban Corps of San Diego County","provides":"Paid job training and a second chance at a diploma for young adults.","eligibility":"Young adults ages 18 to 26 in San Diego County","apply":"Apply online at urbancorpssd.org to join as a Corpsmember","url":"https://urbancorpssd.org/","status":"Confirm current status","status_note":"Enrollment windows vary","source":"https://urbancorpssd.org/","date_checked":"2026-09-04"},{"id":"second-chance-wioa","pillar":"Free Regenerative Independent Personal Income","name":"Second Chance - WIOA Youth Employment Program","provides":"Paid job training, internships, and job-readiness help for young people.","eligibility":"Youth in San Diego County, including those involved with the justice system","apply":"Contact Second Chance to enroll in the WIOA youth program","phone":"(619) 234-8888","url":"https://www.secondchanceprogram.org/","status":"Confirm current status","status_note":"Enrollment windows vary","source":"https://www.secondchanceprogram.org/","date_checked":"2026-09-04"},{"id":"sdhs-pet-pantry","pillar":"Free Food Resources","name":"San Diego Humane Society - Community Pet Pantry","provides":"Free bags of dog or cat food and other pet supplies, with no appointment needed, at four San Diego Humane Society campuses across the county plus monthly neighborhood giveaways.","eligibility":"Open to anyone - no income check or appointment required","apply":"Walk into any campus during open hours (Tue-Sun, 10am-6pm): El Cajon, Escondido, Oceanside, or San Diego (5480 Gaines St.); check the page for rotating neighborhood distribution sites","phone":"619-299-7012","url":"https://sdhumane.org/services/community-pet-pantry/","status":"Open","status_note":"Neighborhood distribution dates rotate - confirm the monthly site before traveling","source":"https://sdhumane.org/services/community-pet-pantry/","date_checked":"2026-09-05"},{"id":"rchs-pet-food-bank","pillar":"Free Food Resources","name":"Rancho Coastal Humane Society - Brock's Community Pet Food Bank","provides":"Free supplemental dog and cat food plus pet-care supplies for pet parents who need a hand, at the Encinitas campus and partner distribution sites around San Diego County.","eligibility":"Open to pet parents in need; no appointment; partner-site eligibility may vary","apply":"Visit 389 Requeza St., Encinitas, any Saturday 9-11 a.m.; ask about other sites","phone":"(760) 753-6413","url":"https://rchumanesociety.org/pet-food-bank/","status":"Open","status_note":"Partner-site schedules may change - call first","source":"https://rchumanesociety.org/pet-food-bank/","date_checked":"2026-09-05"},{"id":"chula-vista-pet-pantry","pillar":"Free Food Resources","name":"Chula Vista Animal Care Facility - Pet Food Pantry","provides":"Free dog and cat food for residents in need, handed out once a month with drop-ins welcome.","eligibility":"Chula Vista residents (county listing also includes Lemon Grove and National City)","apply":"Drop in on the 2nd Thursday of the month, 11am-12pm, at 130 Beyer Way, Chula Vista; or email animalcare@chulavistaca.gov to confirm the next date","url":"https://www.chulavistaca.gov/departments/animal-care/pet-ownership-assistance/services-page","status":"Confirm current status","status_note":"No pantry phone published - contact the city animal-care office before going","source":"https://www.chulavistaca.gov/departments/animal-care/pet-ownership-assistance/services-page","date_checked":"2026-09-05"},{"id":"sdhs-community-vet-clinic","pillar":"Free Universal Health","name":"San Diego Humane Society - Community Veterinary Clinic (campus + mobile)","provides":"Low-cost veterinary care - exams, vaccines, flea medicine, spay and neuter, and basic sick care - at the San Diego campus and mobile clinics in under-served neighborhoods.","eligibility":"Household income under $100k/yr, or enrolled in SSI, SNAP/CalFresh, SSDI, WIC, other assistance, or unemployment. Sliding fees (exam $50; vaccines $28-35)","apply":"Call 858-216-3908 for an appointment (Tue-Sat); check the page for mobile clinic dates. No emergency care.","phone":"858-216-3908","url":"https://sdhumane.org/services/low-cost-veterinary-services/community-veterinary-clinic/","status":"Open","status_note":"Mobile clinic dates listed into 2027; deposits nonrefundable, 48-hour cancellation notice","source":"https://sdhumane.org/services/low-cost-veterinary-services/community-veterinary-clinic/","date_checked":"2026-09-05"},{"id":"pets-without-walls","pillar":"Free Universal Health","name":"Helen Woodward Animal Center - Pets Without Walls","provides":"Free mobile veterinary clinics for people experiencing homelessness, low-income seniors, and veterans - health checks, vaccines, microchipping, flea and tick medicine, and spay/neuter - at no cost to the owner.","eligibility":"Unhoused individuals, low-income seniors, and veterans; first-come first-served, limited spots","apply":"Call (858) 756-4117 x339 or email outreach@animalcenter.org for the next public clinic date (Father Joe's Neil Good Day Center, 299 17th St., San Diego; sign-up 8am, services 9am)","phone":"(858) 756-4117 x339","url":"https://animalcenter.org/pets-without-walls/","status":"Open - confirm next clinic date","status_note":"Clinic dates rotate and capacity is limited - always confirm the exact next date before showing up","source":"https://animalcenter.org/pets-without-walls/","date_checked":"2026-09-05"},{"id":"project-street-vet","pillar":"Free Universal Health","name":"Project Street Vet - San Diego","provides":"Free veterinary care, supplies, and medicines at street-outreach and partner clinics, plus financial-assistance grants for pet care.","eligibility":"Pets of people experiencing homelessness or housing vulnerability in San Diego; screening application for financial assistance","apply":"Fill out the request form at projectstreetvet.org/get-help; urgent needs prioritized","url":"https://www.projectstreetvet.org/locations/san-diego","status":"Open","status_note":"Small team may not respond to every request - pair with other resources","source":"https://www.projectstreetvet.org/get-help","date_checked":"2026-09-05"},{"id":"street-dog-coalition","pillar":"Free Universal Health","name":"The Street Dog Coalition - San Diego (Ocean Beach) Clinics","provides":"Free monthly walk-up veterinary clinics in Ocean Beach offering exams, vaccinations, parasite control, and spay/neuter vouchers for dogs and cats of people experiencing homelessness.","eligibility":"People experiencing or at risk of homelessness; dogs and cats only; first-come first-served","apply":"Show up on the 4th Saturday of the month, 8:30-10 a.m., at the Episcopal Diocese of San Diego, 2083 Sunset Cliffs Blvd., with your pet leashed or in a carrier; check the events page for the current date","url":"https://www.thestreetdogcoalition.org/san-diego-ca","status":"Open - dates subject to change","status_note":"Clinic dates rotate monthly - always check the events page first","source":"https://www.thestreetdogcoalition.org/clinics-and-events/san-diego-ocean-beach-clinic-sept26","date_checked":"2026-09-05"},{"id":"sdhs-safety-net-foster","pillar":"Free Independent Personal Housing","name":"San Diego Humane Society - Safety Net Foster Program","provides":"Free temporary foster homes for your pet while you deal with housing insecurity, domestic violence, or a hospital stay, so you can keep your pet instead of giving it up; SDHS provides all care supplies and aims to reunite you within 90 days.","eligibility":"San Diego County resident in financial hardship with no other boarding option; owned pet 3+ months (max 3 pets); reunite within 90 days","apply":"Call 619-299-7012 to request the program application; staff follow up within about 72 hours","phone":"619-299-7012","url":"https://sdhumane.org/services/temporary-pet-care/","status":"Open","status_note":"Limited capacity, case-by-case; $30 microchip/license fees at reclaim; no visits during foster; extensions past 30 days not guaranteed","source":"https://sdhumane.org/services/temporary-pet-care/","date_checked":"2026-09-05"},{"id":"sd-211-pets","pillar":"Free Independent Personal Housing","name":"2-1-1 San Diego - Pet-Friendly Shelter and Housing Line","provides":"A free 24-hour phone line and online database that helps you find pet-friendly shelters, safe parking lots, and other housing help across San Diego County, so your pet can come with you.","eligibility":"Anyone in San Diego County - free and confidential","apply":"Dial 211 (or visit 211sandiego.org) and ask for pet-friendly shelters, safe parking, and pet-inclusive housing options","phone":"211","url":"https://211sandiego.org/housing-information/","status":"Open","status_note":"City of San Diego confirms its contracted shelters and JFS Safe Parking allow domestic pets","source":"https://sdhumane.org/resources/pet-inclusive-housing-support/","date_checked":"2026-09-05"},{"id":"hud-assistance-animals","pillar":"Free Independent Personal Housing","name":"HUD - Assistance Animal Rights under the Fair Housing Act","provides":"Under the Fair Housing Act, a housing provider must let you keep an assistance animal - a trained service animal or an emotional support animal - as a reasonable accommodation, even in no-pets housing, with no pet deposits or breed/size limits, with only narrow legal exceptions.","eligibility":"You or a household member must have a disability, and the animal must work for, assist, or provide emotional support that alleviates the disability; a letter from a doctor, therapist, or social worker is the standard supporting document","apply":"Ask your housing provider in writing for a reasonable accommodation; if denied, file a complaint with HUD's Fair Housing and Equal Opportunity office at (800) 669-9777","phone":"(800) 669-9777","url":"https://www.hud.gov/helping-americans/assistance-animals","status":"Right in effect - federal enforcement narrowed May 2026","status_note":"Honesty flag: HUD's FHEO enforcement guidance (May 22, 2026) pursues animal-accommodation complaints only for animals individually trained to perform disability-related tasks - untrained ESAs are no longer prioritized by HUD enforcement, though Fair Housing Act / Section 504 obligations and private legal action still exist","source":"https://www.hud.gov/helping-americans/assistance-animals","date_checked":"2026-09-05"},{"id":"sdhs-vaccination-clinics","pillar":"Free Universal Health","name":"San Diego Humane Society - Vaccination & Microchipping Clinics","provides":"Low-cost vaccines and microchips for dogs and cats, with no income requirement, at walk-in clinic events.","eligibility":"No income requirement; $30 vaccine/microchip; walk-ins +$15","apply":"Check the SDHS vaccination & microchipping page for the current clinic schedule; call 619-299-7012 with questions","phone":"619-299-7012","url":"https://sdhumane.org/services/low-cost-veterinary-services/vaccinations-microchipping/","status":"Open","status_note":"Confirm current clinic dates on the page before traveling","source":"https://sdhumane.org/services/low-cost-veterinary-services/vaccinations-microchipping/","date_checked":"2026-09-05"},{"id":"pets-of-the-homeless","pillar":"Free Universal Health","name":"Pets of the Homeless","provides":"National nonprofit supporting homeless pet families with pet food and urgent vet-care grants, listed by San Diego Humane Society as a resource.","eligibility":"People experiencing homelessness with pets","apply":"Contact via petsofthehomeless.org or call 775-841-7463","phone":"775-841-7463","url":"https://petsofthehomeless.org/","status":"Confirm current status","status_note":"National organization - confirm current San Diego-area services via their site","source":"https://petsofthehomeless.org/","date_checked":"2026-09-05"}]`);export{e as r};
